function kthHighest(bids, k) {
  const a = [...bids]
  const target = a.length - k
  let lo = 0
  let hi = a.length - 1
  for (;;) {
    const mid = (lo + hi) >> 1
    ;[a[mid], a[hi]] = [a[hi], a[mid]]
    const pivot = a[hi]
    let store = lo
    for (let j = lo; j < hi; j++) {
      if (a[j] < pivot) {
        ;[a[store], a[j]] = [a[j], a[store]]
        store++
      }
    }
    ;[a[store], a[hi]] = [a[hi], a[store]]
    if (store === target) return a[store]
    if (store < target) lo = store + 1
    else hi = store - 1
  }
}

