def kth_highest(bids, k):
    a = list(bids)
    target = len(a) - k
    lo, hi = 0, len(a) - 1
    while True:
        mid = (lo + hi) // 2
        a[mid], a[hi] = a[hi], a[mid]
        pivot, store = a[hi], lo
        for j in range(lo, hi):
            if a[j] < pivot:
                a[store], a[j] = a[j], a[store]
                store += 1
        a[store], a[hi] = a[hi], a[store]
        if store == target:
            return a[store]
        if store < target:
            lo = store + 1
        else:
            hi = store - 1
